import { z } from 'zod';

export const XIdSchema = z.string().regex(/^\d{1,19}$/);
export const XAccountSchema = z.object({
  id: XIdSchema,
  username: z.string().regex(/^[A-Za-z0-9_]{1,15}$/),
  name: z.string().max(200).optional(),
});
export const XMediaUrlSchema = z
  .string()
  .url()
  .refine((value) => {
    const url = new URL(value);
    return (
      url.protocol === 'https:' &&
      url.hostname === 'pbs.twimg.com' &&
      !url.username &&
      !url.password &&
      !url.port
    );
  });
export const XBookmarkSchema = z.object({
  id: XIdSchema,
  author: XAccountSchema,
  text: z.string().max(100_000),
  links: z.array(z.string().url()),
  unavailableVideoCount: z.number().int().nonnegative().default(0),
  media: z
    .array(
      z.object({
        key: z.string().min(1),
        url: XMediaUrlSchema,
        representation: z.enum(['image', 'video-cover']),
        altText: z.string().nullable(),
      }),
    )
    .max(100),
});
export const XBookmarksPageSchema = z.object({
  bookmarks: z.array(XBookmarkSchema),
  nextCursor: z.string().min(1).nullable(),
});
export const XBookmarksResultSchema = z.discriminatedUnion('status', [
  XBookmarksPageSchema.extend({
    status: z.literal('ok'),
    account: XAccountSchema,
  }),
  z.object({ status: z.literal('not_connected') }),
  z.object({
    status: z.literal('error'),
    message: z.string(),
    reason: z
      .enum(['rate_limited', 'account_changed', 'provider_unavailable'])
      .optional(),
    retryAfterMs: z.number().nonnegative().optional(),
  }),
]);
export type XAccount = z.infer<typeof XAccountSchema>;
export type XBookmark = z.infer<typeof XBookmarkSchema>;
export type XBookmarksPage = z.infer<typeof XBookmarksPageSchema>;
export type XBookmarksResult = z.infer<typeof XBookmarksResultSchema>;
